// Giả lập một API chậm (trong thực tế bạn dùng fetch)
function fakeFetchUser(id) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (id === 1) resolve({ id: 1, name: "Lexi" });
      else reject(new Error("Không tìm thấy"));
    }, 50);
  });
}

async function main() {
  try {
    const user = await fakeFetchUser(1);   // chờ xong mới chạy dòng kế
    console.log("Xin chào", user.name);
    await fakeFetchUser(99);               // bị reject → nhảy vào catch
  } catch (error) {
    console.log("Lỗi:", error.message);
  } finally {
    console.log("xong");
  }
}
main();

